/**
 * RenderRequest
 *
 * Options for rendering a session's frames into a video. Omitted fields use ``video.*``
 * from the app config.
 */
export type RenderRequest = {
    /**
     * Bracket Frame
     *
     * Which shot of each bracket set to use: middle, first, last or a zero-based step index (>= 0; an index past the end of a set uses its last shot).
     */
    bracket_frame?: 'middle' | 'first' | 'last' | number;
    /**
     * Codec
     *
     * h264, h265 (mp4), prores (mov) or vp9 (webm).
     */
    codec?: 'h264' | 'h265' | 'prores' | 'vp9' | null;
    /**
     * Crf
     *
     * Constant rate factor (lower is better).
     */
    crf?: number | null;
    /**
     * Deflicker
     *
     * Apply ffmpeg's deflicker filter.
     */
    deflicker?: boolean;
    /**
     * Fps
     *
     * Output frame rate.
     */
    fps?: number | null;
    /**
     * Output Name
     *
     * File name (sanitised; extension is set by the codec; never overwrites).
     */
    output_name?: string | null;
    /**
     * Preset
     *
     * x264/x265 speed preset.
     */
    preset?: 'ultrafast' | 'superfast' | 'veryfast' | 'faster' | 'fast' | 'medium' | 'slow' | 'slower' | 'veryslow' | null;
    /**
     * Quality
     *
     * Shortcut overriding crf (and the ProRes profile).
     */
    quality?: 'low' | 'medium' | 'high' | null;
    /**
     * Resolution
     *
     * Fit inside this size, keeping aspect ratio.
     */
    resolution?: 'source' | '2160p' | '1080p' | '720p';
};

