export type TimelapseState = 'idle' | 'configured' | 'running' | 'paused' | 'stopping' | 'completed' | 'stopped' | 'failed';

/**
 * TimelapseStatus
 */
export type TimelapseStatus = {
    config?: TimelapseSetup | null;
    counters?: Counters;
    /**
     * Error
     */
    error?: string | null;
    /**
     * Failure Budget
     *
     * Consecutive capture failures that end the run as failed.
     */
    failure_budget?: number;
    last_frame?: LastFrame | null;
    /**
     * Measured Set Duration S
     *
     * Rolling average of the real duration of one shot set.
     */
    measured_set_duration_s?: number | null;
    /**
     * Paused Reason
     */
    paused_reason?: 'user' | 'camera_disconnected' | null;
    /**
     * Session Id
     */
    session_id?: string | null;
    state: TimelapseState;
    timing?: Timing;
    /**
     * Validated
     *
     * The configuration was resolved against a connected camera.
     */
    validated?: boolean;
};

